import json
from pathlib import Path

from django.core.management.base import BaseCommand, CommandError

from apps.core.exceptions import DomainError


class Command(BaseCommand):
    help = "Import the institution's official rubric (JSON) into an internship period."

    def add_arguments(self, parser):
        parser.add_argument("path", help="Path to the assessment form JSON file.")
        parser.add_argument("--period", required=True, help="Internship period id (UUID).")

    def handle(self, *args, **options):
        from apps.assessments.importers import AssessmentFormImporter
        from apps.placements import selectors as placements_selectors

        period = placements_selectors.get_period(options["period"])
        if period is None:
            raise CommandError("Internship period not found.")
        data = json.loads(Path(options["path"]).read_text(encoding="utf-8"))
        try:
            form = AssessmentFormImporter.import_json(period, data)
        except DomainError as exc:
            raise CommandError(exc.message) from exc
        self.stdout.write(self.style.SUCCESS(f"Imported '{form.name}' v{form.version}"))
